package sohal.lld.zerodha.broker;import sohal.lld.zerodha.command.BuyOrderCommand;import sohal.lld.zerodha.command.OrderCommand;import sohal.lld.zerodha.command.SellOrderCommand;import sohal.lld.zerodha.entity.Stock;import sohal.lld.zerodha.order.Order;import sohal.lld.zerodha.user.User;import java.util.Map;import java.util.concurrent.ConcurrentHashMap;public class StockBrokerageSystem {    private static volatile StockBrokerageSystem instance;    private final Map<String, User> users;    private final Map<String, Stock> stocks;    private StockBrokerageSystem() {        users = new ConcurrentHashMap<>();        stocks = new ConcurrentHashMap<>();    }    public static StockBrokerageSystem getInstance() {        if (instance == null) {            synchronized (StockBrokerageSystem.class) {                if (instance == null) {                    instance = new StockBrokerageSystem();                }            }        }        return instance;    }    public User registerUser(String name, double initBalance) {        User user = new User(name, initBalance);        users.put(user.getUserId(), user);        return user;    }    public Stock addStock(String symbol, double initPrice) {        Stock stock = new Stock(symbol, initPrice);        stocks.put(symbol, stock);        return stock;    }    public void placeSellOrder(Order order) {        User user = order.getUser();        OrderCommand command = new SellOrderCommand(user.getAccount(), order);        command.execute();    }    public void placeBuyOrder(Order order) {        User user = order.getUser();        OrderCommand command = new BuyOrderCommand(user.getAccount(), order);        command.execute();    }    public void cancelOrder(Order order) {        order.cancelOrder();    }}